import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_activation_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <math.h>

__global__ void fused_activation_kernel(
    const float* input, 
    const float* add_value,
    float* output,
    int batch_size,
    int out_features
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_features;

    if (idx < total_elements) {
        int col = idx % out_features;
        float x = input[idx] + add_value[col];

        // Swish (x * sigmoid(x))
        float sigmoid_x = 1.0f / (1.0f + expf(-x));
        x = x * sigmoid_x;

        // Tanh
        x = tanhf(x);

        // GELU (exact version)
        float gelu_x = 0.5f * x * (1.0f + erff(x * 0.7071067811865475f));
        x = gelu_x;

        // Hardtanh
        x = fmaxf(-1.0f, fminf(x, 1.0f));

        output[idx] = x;
    }
}

torch::Tensor fused_activation_cuda(torch::Tensor input, torch::Tensor add_value) {
    auto output = torch::zeros_like(input);
    int total_elements = input.numel();
    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int out_features = sizes[1];

    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_activation_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        add_value.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        out_features
    );

    return output;
}
"""

fused_activation_cpp = "torch::Tensor fused_activation_cuda(torch::Tensor input, torch::Tensor add_value);"

fused_activation = load_inline(
    name='fused_activation',
    cpp_sources=fused_activation_cpp,
    cuda_sources=fused_activation_source,
    functions=['fused_activation_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, add_value_shape):
        super(ModelNew, self).__init__()
        self.matmul = nn.Linear(in_features, out_features)
        self.add_value = nn.Parameter(torch.randn(add_value_shape))
        self.fused_activation = fused_activation

    def forward(self, x):
        x = self.matmul(x)
        x = self.fused_activation.fused_activation_cuda(x, self.add_value)
        return x
